async function main(): Promise<void> {
  const gen: any = new Function('return (async function* () { try { yield 1; yield 2; yield 3; } finally { console.log("cleanup"); } })()')();
  for await (const x of gen) { console.log('x', x); if (x === 2) break; }
  console.log('after break');
  const bad: any = new Function('return { [Symbol.asyncIterator]() { return { next() { return Promise.reject(new Error("boom")); } }; } }')();
  try { for await (const q of bad) { console.log('q'); } } catch (e: any) { console.log('caught', e.message); }
  const notIt: any = 5;
  try { for await (const z of notIt) { console.log('z'); } } catch (e: any) { console.log('caught2', e instanceof TypeError); }
}
